SELECT p.discharged_home, p.discharged_to_hospice, p.in_hospital_mortality, AVG(a.los) AS average_length_of_stay, STDDEV(a.los) AS standard_deviation_of_length_of_stay FROM patients p JOIN admissions a ON p.subject_id = a.subject_id WHERE p.gender = 'F' AND p.anchor_year_group = '75-85' AND a.admission_type = 'hospital' AND a.discharge_location != 'ICU' GROUP BY p.discharged_home, p.discharged_to_hospice, p.in_hospital_mortality ORDER BY average_length_of_stay NULLS LAST;